INSERT INTO public.problems (
    zone, category, difficulty,
    trick_id, trick_ids,
    stem, answer, answer_type,
    brute_force_path, shortcut_path, shortcut_time_threshold_ms,
    hints, aha_moment, flavor_text, tags,
    estimated_brute_force_seconds, estimated_trick_seconds
) VALUES (
    1,
    'pattern',
    1,
    'A1',
    ARRAY['A1'],
    'Zara the explorer finds a locked gate. The code is 11 × 12. What number opens the gate?',
    '132',
    'exact',
    '11×10=110, 11×2=22, 110+22=132',
    'Digit-sum rule: 1+2=3, sandwich → 132',
    10500,
    '[{"level": 1, "text": "Look at the two digits of 12 separately. What do they add up to?", "cost": 0}, {"level": 2, "text": "Use the \u00d711 rule: place the digit sum of 12 between its two digits.", "cost": 5}, {"level": 3, "text": "The answer is a 3-digit number: the left digit of 12, then the sum of its digits, then the right digit \u2014 but watch out if the sum is 10 or more!", "cost": 15}]'::jsonb,
    'When multiplying by 11, the middle digit is the sum of the two outer digits — and carry if it overflows!',
    'The ancient ×11 cipher appears in the forest challenge.',
    ARRAY['multiplication', '×11', 'digit-sum', 'zone-1'],
    17,
    4
);

