    trick_id, trick_ids,
    stem, answer, answer_type,
    brute_force_path, shortcut_path, shortcut_time_threshold_ms,
    hints, aha_moment, flavor_text, tags,
    estimated_brute_force_seconds, estimated_trick_seconds
) VALUES (
    3,
    'pattern',
    6,
    'A3',
    ARRAY['A3'],
    'Zara''s scores double each round starting from 6. After 6 doublings (×64), what''s her score?',
    '384',
    'exact',
    '6×64: 6,12,24,48,96,192,384',
    '6→12→24→48→96→192→384',
    8500,
    '[{"level": 1, "text": "Notice that 64 is a power of 2. How many times do you need to double 6 to reach it?", "cost": 0}, {"level": 2, "text": "Use doubling chains: start with 6 and double it until you''ve doubled enough times for \u00d764.", "cost": 5}, {"level": 3, "text": "Write out the doubling sequence starting at 6. Count how many doublings give you \u00d764 total.", "cost": 15}]'::jsonb,
    '×64 = double, double...............! Chain your doublings instead of multiplying directly.',
    'The doubling chain shortcut turns ×64 into simple repeated doubling.',
    ARRAY['multiplication', '×64', 'doubling', 'zone-3'],
    14,
    3
);

