    stem, answer, answer_type,
    brute_force_path, shortcut_path, shortcut_time_threshold_ms,
    hints, aha_moment, flavor_text, tags,
    estimated_brute_force_seconds, estimated_trick_seconds
) VALUES (
    1,
    'pattern',
    1,
    'A5',
    ARRAY['A5'],
    'Mia stacks 2 rows: row 1 has 1 tile, row 2 has 3. Total tiles?',
    '4',
    'exact',
    'Add all 2 odd numbers one by one: result = 4',
    'Sum of first 2 odd numbers = 2² = 4',
    9500,
    '[{"level": 1, "text": "Look at the pattern: 1 odd number gives 1\u00b2, two give 2\u00b2, three give 3\u00b2...", "cost": 0}, {"level": 2, "text": "The sum of the first n odd numbers always equals n\u00b2. Here n = 2, so the answer is 2\u00b2.", "cost": 5}, {"level": 3, "text": "Calculate 2\u00b2 \u2014 that is 2 \u00d7 2. You don''t need to add all the odd numbers individually!", "cost": 15}]'::jsonb,
    '1 + 3 + 5 + … + (2n−1) = n². Count the odd numbers, square that count — done!',
    'The odd-numbers staircase always makes a perfect square grid.',
    ARRAY['pattern', 'odd-numbers', 'perfect-square', 'zone-1'],
    17,
    2
);

