INSERT INTO public.problems (
    zone, category, difficulty,
    trick_id, trick_ids,
    stem, answer, answer_type,
    brute_force_path, shortcut_path, shortcut_time_threshold_ms,
    hints, aha_moment, flavor_text, tags,
    estimated_brute_force_seconds, estimated_trick_seconds
) VALUES (
    1,
    'pattern',
    1,
    'A6',
    ARRAY['A6'],
    'Alex has a 5×5 square cake and Grogg has a 3×3 square hole cut out. How many square cm remain? (5²−3²)',
    '16',
    'exact',
    '5²=25, 3²=9, 25−9=16',
    '(5+3)×(5−3) = 8×2 = 16',
    12000,
    '[{"level": 1, "text": "Can you factor 5\u00b2\u22123\u00b2 into a multiplication? Think about what a\u00b2\u2212b\u00b2 equals.", "cost": 0}, {"level": 2, "text": "Use a\u00b2\u2212b\u00b2=(a+b)(a\u2212b). Here a=5 and b=3, so compute (5+3)\u00d7(5\u22123).", "cost": 5}, {"level": 3, "text": "Apply the difference-of-squares formula to get two factors. Once you have both factors as plain numbers, multiply them together.", "cost": 15}]'::jsonb,
    'a²−b²=(a+b)(a−b). Turn hard subtraction of squares into two easy multiplications!',
    'The difference of squares identity transforms a tough problem into a quick multiply.',
    ARRAY['pattern', 'difference-of-squares', 'factoring', 'zone-1'],
    21,
    3
);

