INSERT INTO public.problems (
    zone, category, difficulty,
    trick_id, trick_ids,
    stem, answer, answer_type,
    brute_force_path, shortcut_path, shortcut_time_threshold_ms,
    hints, aha_moment, flavor_text, tags,
    estimated_brute_force_seconds, estimated_trick_seconds
) VALUES (
    1,
    'invariant',
    1,
    'B1',
    ARRAY['B1'],
    'Alex has 6 apples and Grogg has 4 bananas. They count together. How many fruit in total?',
    '10',
    'exact',
    'Direct computation: 10',
    'Parity check: answer is 10',
    9500,
    '[{"level": 1, "text": "Before computing, decide: will the answer be odd or even? Use the parity rules.", "cost": 0}, {"level": 2, "text": "Recall: Odd+Odd=Even, Even+Even=Even, Odd+Even=Odd. And Odd\u00d7Odd=Odd, anything\u00d7Even=Even. Apply this.", "cost": 5}, {"level": 3, "text": "Identify whether each number in the problem is odd or even, then apply the parity rule step by step to predict the answer''s parity before you compute.", "cost": 15}]'::jsonb,
    'Parity rules let you check your answer instantly — odd×odd=odd, even anywhere in × makes the product even!',
    'Knowing if an answer is odd or even helps you catch mistakes before they happen.',
    ARRAY['number_theory', 'parity', 'odd-even', 'zone-1'],
    17,
    2
);

