    trick_id, trick_ids,
    stem, answer, answer_type,
    brute_force_path, shortcut_path, shortcut_time_threshold_ms,
    hints, aha_moment, flavor_text, tags,
    estimated_brute_force_seconds, estimated_trick_seconds
) VALUES (
    3,
    'invariant',
    6,
    'B3',
    ARRAY['B3'],
    'A chest problem: 5(x−1)=15. How many coins is x?',
    '4',
    'exact',
    '5(3)=15',
    'x−1=3 → x=4',
    8500,
    '[{"level": 1, "text": "Think of the equation as a balanced scale. What can you do to both sides to move the unknown alone?", "cost": 0}, {"level": 2, "text": "Use inverse operations: subtract or add the same number to both sides to start isolating x.", "cost": 5}, {"level": 3, "text": "Collect all x-terms on one side, all numbers on the other. Then divide (or multiply) both sides by the coefficient of x.", "cost": 15}]'::jsonb,
    'An equation is a balanced scale — apply the same operation to both sides and the balance holds!',
    'Balance principle: whatever you do to one side, do to the other.',
    ARRAY['algebra', 'equations', 'balance', 'zone-3'],
    14,
    3
);

