INSERT INTO public.problems (
    zone, category, difficulty,
    trick_id, trick_ids,
    stem, answer, answer_type,
    brute_force_path, shortcut_path, shortcut_time_threshold_ms,
    hints, aha_moment, flavor_text, tags,
    estimated_brute_force_seconds, estimated_trick_seconds
) VALUES (
    1,
    'invariant',
    1,
    'B4',
    ARRAY['B4'],
    'Today is Monday. What day is it 3 days from now?',
    '4',
    'exact',
    'Count: Mon→Tue→Wed→Thu',
    '3 mod 7 = 3 → Thursday (Mon=1,Tue=2,Wed=3,Thu=4)',
    11000,
    '[{"level": 1, "text": "Numbers repeat in cycles when you divide by a fixed amount. What is the cycle length here?", "cost": 0}, {"level": 2, "text": "Find the remainder when your total is divided by the cycle length. That remainder tells you the position in the pattern.", "cost": 5}, {"level": 3, "text": "Divide the large number by the cycle length and note the remainder. The answer corresponds to that remainder in the cycle.", "cost": 15}]'::jsonb,
    'Modular arithmetic = clock arithmetic! Numbers wrap around after reaching the cycle length.',
    'On a clock, after 12 comes 1 — that''s modular arithmetic in everyday life!',
    ARRAY['number_theory', 'modular', 'clock-arithmetic', 'zone-1'],
    19,
    3
);

