    trick_id, trick_ids,
    stem, answer, answer_type,
    brute_force_path, shortcut_path, shortcut_time_threshold_ms,
    hints, aha_moment, flavor_text, tags,
    estimated_brute_force_seconds, estimated_trick_seconds
) VALUES (
    5,
    'mental',
    10,
    'C1',
    ARRAY['C1'],
    '76 × 98 = ? (chunk 98 = 90+8 or 100−2)',
    '7448',
    'exact',
    '76×98=7448',
    '76×100=7600, 76×2=152, 7600−152=7448',
    5000,
    '[{"level": 1, "text": "Can you break one of the numbers into simpler parts (like tens and units) to make the calculation easier?", "cost": 0}, {"level": 2, "text": "Chunking: split the harder number into landmark pieces (hundreds, tens, units), then add (or multiply) each chunk separately.", "cost": 5}, {"level": 3, "text": "Handle the biggest chunk first, then add the smaller chunks one at a time. Write down the running total after each step.", "cost": 15}]'::jsonb,
    'Chunking: split a hard number into easy pieces. Add (or multiply) piece by piece — no carrying confusion!',
    'Breaking numbers into chunks makes hard arithmetic feel like easy steps.',
    ARRAY['mental_math', 'chunking', 'addition', 'zone-5'],
    8,
    2
);

INSERT INTO public.problems (
    zone, category, difficulty,
    trick_id, trick_ids,
    stem, answer, answer_type,
    brute_force_path, shortcut_path, shortcut_time_threshold_ms,
    hints, aha_moment, flavor_text, tags,
    estimated_brute_force_seconds, estimated_trick_seconds
) VALUES (
    5,
    'mental',
    10,
    'C1',
    ARRAY['C1'],
    'Zara has 99 jars with 84 marbles each. Total marbles? (chunk 84 or use 99≈100)',
    '8316',
    'exact',
    '99×84=8316',
    '99×84=100×84−84=8400−84=8316',
    5000,
    '[{"level": 1, "text": "Can you break one of the numbers into simpler parts (like tens and units) to make the calculation easier?", "cost": 0}, {"level": 2, "text": "Chunking: split the harder number into landmark pieces (hundreds, tens, units), then add (or multiply) each chunk separately.", "cost": 5}, {"level": 3, "text": "Handle the biggest chunk first, then add the smaller chunks one at a time. Write down the running total after each step.", "cost": 15}]'::jsonb,
    'Chunking: split a hard number into easy pieces. Add (or multiply) piece by piece — no carrying confusion!',
    'Breaking numbers into chunks makes hard arithmetic feel like easy steps.',
    ARRAY['mental_math', 'chunking', 'addition', 'zone-5'],
    8,
    2
);

INSERT INTO public.problems (
    zone, category, difficulty,
    trick_id, trick_ids,
    stem, answer, answer_type,
    brute_force_path, shortcut_path, shortcut_time_threshold_ms,
    hints, aha_moment, flavor_text, tags,
    estimated_brute_force_seconds, estimated_trick_seconds
) VALUES (
    1,
    'mental',
    1,
    'C2',
    ARRAY['C2'],
    'Mia needs exactly 100 stickers. She has 63. How many more does she need?',
    '37',
    'exact',
    '63+37=100',
    '100−63=37',
    8500,
    '[{"level": 1, "text": "What number adds to the given amount to make a round number (100, 1000, etc.)?", "cost": 0}, {"level": 2, "text": "Use the complement method: subtract from the nearest round number. Work digit by digit from the right.", "cost": 5}, {"level": 3, "text": "For complement to 1000: subtract each digit from 9 (for the hundreds and tens), then subtract the units from 10 \u2014 and adjust if needed.", "cost": 15}]'::jsonb,
    'Every number has a complement that reaches the next round number — find it instantly!',
    'Complement pairs are the fastest way to subtract from round numbers.',
    ARRAY['mental_math', 'complement', 'subtraction', 'zone-1'],
    15,
    2
);

