INSERT INTO public.problems (
    zone, category, difficulty,
    trick_id, trick_ids,
    stem, answer, answer_type,
    brute_force_path, shortcut_path, shortcut_time_threshold_ms,
    hints, aha_moment, flavor_text, tags,
    estimated_brute_force_seconds, estimated_trick_seconds
) VALUES (
    4,
    'invariant',
    7,
    'B2',
    ARRAY['B2'],
    'The rectilinear shape below is made of unit tiles. Find the perimeter.

  ┌──────────────────┐
  │                  │
  │        20        │
  │                  ├──────┐
  │              8   │  8   │
  └──────┬───────────┘      │
     6   │      14          │
         └──────────────────┘

(Top: 20 wide, 8 tall; bottom protrusion: 14 wide, 6 tall, offset 6 from left)',
    '96',
    'exact',
    'Trace: 20+8+8+6+14+6+6+8+8+6+6+6+... count carefully = 96',
    'Perimeter invariance: horiz segments sum = 20+20=40; vert segments sum = 8+6+8+6+...=56. Total=96',
    5000,
    '[{"level": 1, "text": "What are the length and width of the arrangement? The perimeter wraps around all four sides.", "cost": 0}, {"level": 2, "text": "Use the formula: Perimeter = 2 \u00d7 (length + width). Find both dimensions first.", "cost": 5}, {"level": 3, "text": "Add the length and width together, then double the result. The area (total tiles) stays fixed \u2014 only the shape changes the perimeter.", "cost": 15}]'::jsonb,
    'Same area, different shape = different perimeter. Area is fixed, perimeter varies!',
    'Rearranging tiles keeps area the same but can dramatically change the perimeter.',
    ARRAY['pattern', 'perimeter', 'area', 'invariant', 'zone-4'],
    8,
    2
);

