);

INSERT INTO public.problems (
    zone, category, difficulty,
    trick_id, trick_ids,
    stem, answer, answer_type,
    brute_force_path, shortcut_path, shortcut_time_threshold_ms,
    hints, aha_moment, flavor_text, tags,
    estimated_brute_force_seconds, estimated_trick_seconds
) VALUES (
    1,
    'structural',
    1,
    'D4',
    ARRAY['D4'],
    'Mia''s chain letter: she sends to 2 friends, each sends to 2 more. Round 1: 2, Round 2: 4. Total sent in 2 rounds?',
    '6',
    'exact',
    '2+4=6',
    '2+4=6 = 2(2²−1)/(2−1)=6',
    10500,
    '[{"level": 1, "text": "Is each term a fixed multiple of the previous one? What is that ratio?", "cost": 0}, {"level": 2, "text": "Geometric series formula: sum = first \u00d7 (ratio^n \u2212 1) / (ratio \u2212 1). Identify the first term, ratio, and number of terms.", "cost": 5}, {"level": 3, "text": "For ratio=2: sum of n terms = 2^n \u2212 1 (if first term is 1). For other ratios: apply the formula. Write out first, ratio, and n before computing.", "cost": 15}]'::jsonb,
    'Geometric sum formula: a(rⁿ−1)/(r−1). For r=2 and first=1: sum = 2ⁿ−1 — memorize it!',
    'Doubling sequences grow shockingly fast — the sum is always one less than the next power.',
    ARRAY['sequences', 'geometric-series', 'powers', 'zone-1'],
    19,
    2
);

