INSERT INTO public.problems (
    zone, category, difficulty,
    trick_id, trick_ids,
    stem, answer, answer_type,
    brute_force_path, shortcut_path, shortcut_time_threshold_ms,
    hints, aha_moment, flavor_text, tags,
    estimated_brute_force_seconds, estimated_trick_seconds
) VALUES (
    5,
    'structural',
    10,
    'D3',
    ARRAY['D3'],
    'Mia''s ultimate Sym-Sum: 6 symbols a,b,c,d,e,f. Every triplet row sums to 60. a+b+c=60, b+c+d=60, c+d+e=60, d+e+f=60, a+c+e=60, b+d+f=60. If a=25 and b=15, find f.',
    '20',
    'exact',
    'a+b+c=60→c=20; b+c+d=60→d=25; c+d+e=60→e=15; d+e+f=60→f=20',
    'f=60−d−e=60−25−15=20',
    7500,
    '[{"level": 1, "text": "Start with the equation you know the most variables of: a+b+c=60. You already know a and b.", "cost": 0}, {"level": 2, "text": "Find c first, then use overlapping equations to find d, then e, then f \u2014 each equation shares variables with the previous.", "cost": 5}, {"level": 3, "text": "Chain through the equations in order: c from equation 1, d from equation 2, e from equation 3, then f from equation 4.", "cost": 15}]'::jsonb,
    'Chaining overlapping equations: each unknown unlocks the next!',
    'The ultimate Sym-Sum — six symbols locked in a web of balanced equations.',
    ARRAY['algebra', 'balance', 'sym-sum', 'equilibrium', 'zone-5'],
    12,
    3
);

